INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(63193536, 'Over Capacity', '重量超过', '重量オーバー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方对怪兽的特殊召唤成功时才能发动。场上的2星以下的怪兽全部从游戏中除外。'),
(72204747, 'Over Destiny', '超越命运', 'オーバー・デステニー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只「命运英雄」怪兽为对象才能发动。把持有那只怪兽的等级一半以下的等级的1只「命运英雄」怪兽从卡组特殊召唤。这个效果特殊召唤的怪兽在这个回合的结束阶段破坏。'),
(52553471, 'Over Fusion', '结合超涡', '融合超渦', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以场上1只表侧表示怪兽为对象才能发动。从手卡·卡组·额外卡组选「元素英雄」怪兽、「新空间侠」怪兽、10星怪兽之内1只给对方观看。这个回合，把作为对象的怪兽作为融合素材的场合，可以当作给人观看的怪兽的同名卡使用。自己的场上或者墓地有「元素英雄 新宇侠」存在的场合，给人观看的怪兽送去墓地。那以外的场合，从手卡给人观看的怪兽回到卡组。'),
(23282832, 'Over Limit', '超越界限', 'オーバーリミット', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '支付500基本分。这个回合被战斗破坏的攻击力1000以下的通常怪兽尽可能在自己场上特殊召唤。'),
(613496, 'Over Tuning', '超频协调', 'オーバー・チューニング', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有调整存在的场合才能发动。从自己的手卡·卡组·墓地把1只调整特殊召唤。这张卡的发动后，直到回合结束时自己不是同调怪兽不能从额外卡组特殊召唤。'),
(15627227, 'Overburst Dragon', '再装填龙', 'リローダー・ドラゴン', 'Link Monster', 'Dragon', 'DARK', NULL, 1800, NULL, '「弹丸」怪兽2只 这个卡名的①的效果1回合只能使用1次。 ①：以这张卡以外的自己场上1只连接怪兽为对象才能发动。从手卡把1只「弹丸」怪兽在作为那张卡所连接区的自己场上特殊召唤。这个效果特殊召唤的怪兽不能作为连接素材，结束阶段破坏。 ②：这张卡被战斗破坏送去墓地时，以自己墓地1只「弹丸」怪兽为对象才能发动。那只怪兽加入手卡。'),
(65993085, 'Overdone Burial', '过火的埋葬', 'やりすぎた埋葬', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡丢弃1只怪兽，以原本等级比丢弃的怪兽低的自己墓地1只怪兽为对象才能把这张卡发动。那只怪兽特殊召唤，把这张卡装备。 ②：装备怪兽的效果无效化。'),
(87046457, 'Overdoom Line', '超越死线', 'オーバー・デッド・ライン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，从墓地在自己场上特殊召唤的植物族怪兽的攻击力上升1000。这张卡在发动后第2次的自己的结束阶段时破坏。'),
(2311603, 'Overdrive', '机关炮装甲车', 'ガトリングバギー', 'Normal Monster', 'Machine', 'EARTH', 4, 1600, 1500, '装备着重型机枪的装甲车，再恶劣的地形都能逾越。'),
(1834753, 'Overdrive Teleporter', '极限瞬动者', 'マックス・テレポーター', 'Effect Monster', 'Psychic', 'LIGHT', 6, 2100, 1200, '这张卡不能特殊召唤。可以支付2000基本分，从自己卡组把2只3星的念动力族怪兽在自己场上特殊召唤。这个效果只在这张卡在场上表侧表示存在能使用1次。'),
(96352712, 'Overexaggeration', '夸大化', '誇大化', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：怪兽之间进行战斗的伤害步骤开始时，可以从以下效果选择1个发动。 ●那只攻击怪兽变成守备表示。 ●那只攻击对象怪兽回到手卡。 ●那2只进行战斗的怪兽破坏。'),
(76589546, 'Overflow Dragon', '溢出龙', 'オーバーフロー・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 1, NULL, NULL, '这个卡名的效果1回合只能使用1次。 ①：场上的怪兽被效果破坏时才能发动。这张卡从手卡特殊召唤。2只以上的场上的怪兽被效果破坏时发动的场合，可以再在自己场上把1只「溢出衍生物」（龙族·暗·1星·攻/守0）特殊召唤。'),
(75214390, 'Overlay Booster', '叠放推进者', 'オーバーレイ・ブースター', 'Effect Monster', 'Warrior', 'LIGHT', 5, 2000, NULL, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：自己场上有攻击力2000以上的怪兽存在的场合，这张卡可以从手卡守备表示特殊召唤。 ②：把这个回合没有送去墓地的这张卡从墓地除外，以持有超量素材的自己场上1只超量怪兽为对象才能发动。那只怪兽的攻击力上升自身的超量素材数量×500。'),
(74852810, 'Overlay Capture', '叠光捕获', 'オーバーレイ・キャプチャー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择对方场上1只持有超量素材的超量怪兽和自己场上1只超量怪兽才能发动。把选择的对方怪兽的超量素材全部取除，把这张卡在选择的自己怪兽下面重叠作为超量素材。'),
(81816475, 'Overlay Eater', '叠光吞噬者', 'オーバーレイ・イーター', 'Effect Monster', 'Reptile', 'LIGHT', 2, 300, 800, '自己的主要阶段时，把墓地的这张卡从游戏中除外才能发动。把对方场上1个超量素材在自己场上的超量怪兽下面重叠作为超量素材。'),
(67378935, 'Overlay Network', '叠放网络', 'オーバーレイ・ネットワーク', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：可以从以下效果选择1个发动。 ●以自己场上1只表侧表示怪兽为对象才能发动。从自己的手卡·墓地选持有和那只怪兽相同等级的1只怪兽效果无效守备表示特殊召唤。这个效果发动的回合，自己不是超量怪兽不能从额外卡组特殊召唤。 ●以自己场上1只超量怪兽为对象才能发动。那只怪兽作为超量素材中的1张卡加入持有者手卡。'),
(59644958, 'Overlay Owl', '叠光猫头鹰', 'オーバーレイ・オウル', 'Effect Monster', 'Winged Beast', 'WIND', 4, 800, 1600, '1回合1次，支付600基本分才能发动。把场上1个超量素材取除。'),
(27068117, 'Overlay Regen', '叠放再生', 'オーバーレイ・リジェネレート', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择场上存在的1只超量怪兽才能发动。把这张卡在选择的怪兽下面重叠作为超量素材。'),
(39229392, 'Overlay Sentinel', '叠光狙击者', 'オーバーレイ・スナイパー', 'Effect Monster', 'Warrior', 'LIGHT', 4, 2000, NULL, '这张卡不能特殊召唤。这张卡召唤成功时，变成守备表示。此外，自己场上有持有超量素材的超量怪兽存在的场合，把墓地的这张卡从游戏中除外，选择对方场上1只怪兽才能发动。选择的怪兽的攻击力下降自己场上的超量素材数量×500的数值。'),
(3659803, 'Overload Fusion', '超负载结合', 'オーバーロード・フュージョン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的场上·墓地的怪兽作为融合素材除外，把1只机械族·暗属性的融合怪兽融合召唤。'),
(33099732, 'Overload Future Fusion', '超未来融合－超永望结合', '超未来融合－オーバーフューチャー・フュージョン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●把额外卡组1只融合怪兽给对方观看，那只怪兽有卡名记述的1只融合素材怪兽从卡组送去墓地。这个回合，自己不能把这个效果送去墓地的怪兽以及那些同名怪兽特殊召唤，不能把那些怪兽效果发动。 ●自己墓地的怪兽作为融合素材除外，把1只机械族·暗属性的融合怪兽融合召唤。'),
(24221808, 'Overmind Archfiend', '心灵超载恶魔', 'メンタルオーバー・デーモン', 'Synchro Monster', 'Psychic', 'DARK', 9, 3300, 3000, '念动力族调整＋调整以外的念动力族怪兽2只以上 1回合1次，可以选择自己墓地存在的1只念动力族怪兽从游戏中除外。这张卡从场上送去墓地时，这张卡的效果除外的怪兽尽可能在自己场上特殊召唤。'),
(60577362, 'Overpowering Eye', '威压之魔眼', '威圧する魔眼', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只攻击力2000以下的不死族怪兽为对象才能发动。这个回合，那只怪兽可以直接攻击。'),
(41782653, 'Overtex Qoatlus', '超顶风神翼龙', 'オーバーテクス・ゴアトルス', 'Effect Monster', 'Dinosaur', 'DARK', 7, 2700, 2100, '这张卡不能通常召唤。让除外的5只自己的恐龙族怪兽回到卡组的场合才能特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，对方把魔法·陷阱卡发动时才能发动。选自己的手卡·场上1只恐龙族怪兽破坏，那个发动无效并破坏。 ②：这张卡被效果送去墓地的场合才能发动。从卡组把1张「进化药」魔法卡加入手卡。'),
(20140382, 'Overwhelm', '势不可挡', 'オーバーウェルム', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '自己场上有7星以上的上级召唤的怪兽表侧表示存在的场合才能发动。陷阱卡或者效果怪兽的效果的发动无效并破坏。'),
(24920410, 'Overwind', '过度猛拧', 'オーバー・レンチ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只名字带有「发条」的怪兽发动。选择的怪兽的攻击力·守备力变成2倍，这个回合的结束阶段时回到手卡。「过度猛拧」在1回合只能发动1张。'),
(71272951, 'Overworked', '性能过剩', 'オーバースペック', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '场上表侧表示存在的怪兽的攻击力比原本攻击力高的场合，那些怪兽全部破坏。'),
(9720537, 'Owner''s Seal', '所有者的刻印', '所有者の刻印', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上的全部怪兽的控制权回归原本持有者。'),
(58071123, 'Oxygeddon', '氧素龙', 'オキシゲドン', 'Effect Monster', 'Dinosaur', 'WIND', 4, 1800, 800, '①：这张卡被和炎族怪兽的战斗破坏送去墓地的场合发动。双方受到800伤害。'),
(83239739, 'Oyster Meister', '牡蛎大王', 'オイスターマイスター', 'Effect Monster', 'Fish', 'WATER', 3, 1600, 200, '这张卡被战斗破坏以外的方法从场上送去墓地时，在自己场上把1只「牡蛎衍生物」（水·1星·鱼族·攻/守0）特殊召唤。'),
(83239740, 'Oyster Token', '牡蛎大王', 'オイスターマイスター', 'Token', 'Fish', NULL, NULL, NULL, NULL, NULL),
(13760677, 'P.M. Captor', 'P·M 捕获者', 'P・M・キャプチャー', 'Pendulum Effect Monster', 'Zombie', 'DARK', 4, 1800, NULL, '①：这张卡战斗破坏怪兽的场合，以自己墓地1只灵摆怪兽为对象才能发动。那只怪兽加入手卡。'),
(28403802, 'P.U.N.K. JAM Dragon Drive', '朋.克.即兴龙舞', 'P.U.N.K.JAMドラゴン・ドライブ', 'Synchro Monster', 'Psychic', 'EARTH', 8, 2700, 2400, '念动力族调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤或者用「朋克」卡的效果特殊召唤的场合，支付600基本分才能发动。从卡组选1只念动力族·3星怪兽加入手卡或送去墓地。 ②：这张卡在墓地存在的状态，对方连锁自己的「朋克」卡的效果的发动把卡的效果发动的场合才能发动。这张卡特殊召唤。'),
(49370016, 'P.U.N.K. JAM Extreme Session', '朋.克.即兴极限演奏会', 'P.U.N.K.JAMエクストリーム・セッション', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合可以使用最多2次。 ①：1回合1次，从自己墓地把1张「朋克」卡除外才能发动。从手卡把1只「朋克」怪兽特殊召唤。 ②：自己场上的念动力族怪兽为让效果发动而支付基本分的场合才能发动。自己抽1张。'),
(11441009, 'P.U.N.K. JAM FEVER!', '朋.克.即兴狂热！', 'P.U.N.K.JAM FEVER！', 'XYZ Monster', 'Psychic', 'LIGHT', 8, 2800, 600, '8星怪兽×2 「朋克即兴狂热！」1回合1次也能在自己场上的「朋克」融合·同调怪兽上面重叠来超量召唤。这个卡名的①②的效果1回合各能使用1次。 ①：支付600基本分，把这张卡1个超量素材取除才能发动。自己抽1张。 ②：自己墓地有念动力族·3星怪兽存在，这张卡以外的怪兽的效果发动时，把这张卡1个超量素材取除才能发动。那个发动无效并破坏。'),
(46037983, 'Paces, Light of the Ghoti', '游魊之灯 佩西斯', 'ゴーティスの灯ペイシス', 'Tuner Monster', 'Fish', 'WATER', 2, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：把场上的这张卡除外才能发动。从手卡把「魊影之灯 佩西斯」以外的1只鱼族怪兽特殊召唤。 ②：这张卡被除外的下个回合的准备阶段才能发动。除外状态的这张卡特殊召唤。 ③：这张卡特殊召唤的对方回合的主要阶段才能发动。用包含这张卡的自己场上的怪兽为素材进行1只鱼族同调怪兽的同调召唤。'),
(2819435, 'Pacifis, the Phantasm City', '幻煌之都 帕西菲斯', '幻煌の都 パシフィス', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这张卡的卡名在规则上当作「海」使用。这张卡的效果发动的回合，自己不能把效果怪兽召唤·特殊召唤。 ①：1回合1次，自己对通常怪兽1只的召唤·特殊召唤成功的场合发动。从卡组把1张「幻煌龙」卡加入手卡。 ②：自己场上没有衍生物存在，对方把魔法·陷阱·怪兽的效果发动的场合才能发动。在自己场上把1只「幻煌龙衍生物」（幻龙族·水·8星·攻/守2000）特殊召唤。'),
(78859567, 'Packet Link', '分组连接', 'パケットリンク', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的主要阶段2才能发动。选自己的手卡·卡组·墓地的2星以下的怪兽任意数量在作为场上的连接怪兽所连接区的自己场上特殊召唤（同名卡最多1张）。'),
(75153328, 'Packet Swap', '强制切断', '強制切断', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以连接怪兽以外的自己场上1只表侧表示怪兽和对方场上1只连接怪兽为对象才能发动。那2只怪兽的控制权交换。'),
(84530620, 'Pahunder', '雷电爸爸', 'OToサンダー', 'Effect Monster', 'Thunder', 'LIGHT', 4, 1300, 600, '1回合1次，自己的主要阶段时才能发动。从手卡把「雷电爸爸」以外的1只雷族·光属性·4星的怪兽召唤。'),
(21620076, 'Pain Painter', '痛苦绘制者', 'ペインペインター', 'Tuner Monster', 'Zombie', 'DARK', 2, 400, 200, '这张卡的卡名只要在场上表侧表示存在当作「僵尸带菌者」使用。此外，1回合1次，选择这张卡以外的自己场上最多2只不死族怪兽才能发动。选择的怪兽的等级直到结束阶段时变成2星。把这个效果适用的怪兽作为同调素材的场合，不是不死族怪兽的同调召唤不能使用。'),
(74191942, 'Painful Choice', '苦涩的选择', '苦渋の選択', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从卡组选择5张卡给对方看。对方从这些卡中选择1张。对方选择的卡加入自己手卡，其他的卡丢弃去墓地。'),
(1033312, 'Painful Decision', '苦涩的决断', '苦渋の決断', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1只4星以下的通常怪兽送去墓地，那1只同名怪兽从卡组加入手卡。'),
(20513882, 'Painful Escape', '苦涩的默札', '苦渋の黙札', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只怪兽解放才能发动。从自己的卡组·墓地选和解放的怪兽是原本卡名不同并是原本的种族·属性·等级相同的1只怪兽加入手卡。'),
(57902193, 'Painful Return', '苦涩的转生', '苦渋の転生', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从自己墓地由对方选1只怪兽。这个回合的结束阶段时，那只怪兽从墓地加入自己手卡。'),
(21501961, 'Pair Bear Scare!!', '恐依的情侣款凶熊！！', '恐依のペアルックマ！！', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果在决斗中只能使用1次。 ①：对方可以从自身的手卡·卡组把1张「恐依的情侣款凶熊！！」给人观看。给人观看的场合，双方回复2000基本分。没给人观看的场合，自己把对方场上1只怪兽破坏。 ②：这张卡从场上送去墓地的场合发动。这张卡加入对方手卡。'),
(16114248, 'Pair Cycroid', '双人单车机人', 'ペアサイクロイド', 'Fusion Monster', 'Machine', 'EARTH', 5, 1600, 1200, '同名机械族怪兽×2 ①：这张卡可以直接攻击。'),
(300202006, 'Pal-O''Mine-zation!', NULL, NULL, 'Skill Card', 'Joey', NULL, NULL, NULL, NULL, NULL),
(61557074, 'Palace of the Elemental Lords', '灵神的圣殿', '霊神の聖殿', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己场上的怪兽的攻击力·守备力上升自己墓地的怪兽的属性种类×200。 ②：1回合1次，自己主要阶段才能发动。从卡组把1只「元素灵剑士」怪兽加入手卡。那之后，下次的自己回合的战斗阶段跳过。 ③：1回合1次，自己的手卡·场上的「元素灵剑士」怪兽为让效果发动而把手卡送去墓地的场合，可以作为代替把卡组的「元素灵剑士」怪兽送去墓地。'),
(71408082, 'Paladin of Dark Dragon', '黑龙之圣骑士', '黒竜の聖騎士', 'Ritual Effect Monster', 'Dragon', 'DARK', 4, 1900, 1200, '「黑龙降临」降临。「黑龙之圣骑士」的②的效果1回合只能使用1次。 ①：这张卡向守备表示怪兽攻击的伤害步骤开始时发动。那只怪兽破坏。 ②：把这张卡解放才能发动。从手卡·卡组把1只「真红眼」怪兽特殊召唤。'),
(6075801, 'Paladin of Felgrand', '巨龙之圣骑士', '巨竜の聖騎士', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1700, 300, '①：这张卡召唤·特殊召唤成功的场合才能发动。从自己的手卡·卡组把1只7·8星的龙族怪兽当作装备卡使用给这张卡装备。 ②：有装备卡装备的这张卡不受其他怪兽的效果影响。 ③：把自己场上1只怪兽和这张卡解放，以自己墓地1只7·8星的龙族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(85346853, 'Paladin of Photon Dragon', '光子龙之圣骑士', '光子竜の聖騎士', 'Ritual Effect Monster', 'Warrior', 'LIGHT', 4, 1900, 800, '「光子龙降临」降临。把这张卡解放才能发动。从手卡·卡组把1只「银河眼光子龙」特殊召唤。此外，这张卡战斗破坏对方怪兽送去墓地时，从卡组抽1张卡。'),
(86401517, 'Paladin of Storm Dragon', '岚龙圣骑', '嵐竜の聖騎士', 'Ritual Effect Monster', 'Cyberse', 'LIGHT', 4, 1900, 900, '「电脑网仪式」降临。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡向怪兽攻击的伤害步骤开始时才能发动。那只怪兽回到持有者手卡。 ②：把这张卡解放才能发动。从手卡·卡组把1只5星以上的电子界族怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不能把效果发动。'),
(68670547, 'Paladin of the Cursed Dragon', '暗龙之黑骑士', '闇竜の黒騎士', 'Effect Monster', 'Zombie', 'LIGHT', 4, 1900, 1200, '①：1回合1次，以被战斗破坏的对方墓地1只4星以下的不死族怪兽为对象才能发动。那只不死族怪兽在自己场上特殊召唤。'),
(73398797, 'Paladin of White Dragon', '白龙之圣骑士', '白竜の聖騎士', 'Ritual Effect Monster', 'Dragon', 'LIGHT', 4, 1900, 1200, '「白龙降临」降临。 ①：这张卡向里侧守备表示怪兽攻击的伤害步骤开始时发动。那只里侧守备表示怪兽破坏。 ②：把这张卡解放才能发动。从手卡·卡组把1只「青眼白龙」特殊召唤。这个回合，自己的「青眼白龙」不能攻击。'),
(99217226, 'Paladins of Bonds and Unity', '团结与羁绊的超魔导剑士', '結束と絆の超魔導剣士', 'Synchro Monster', 'Spellcaster', 'LIGHT', 12, 2900, 2900, '调整＋调整以外的原本攻击力和原本守备力是2500的怪兽1只以上 ①：只要同调召唤的这张卡在怪兽区域存在，这张卡不会被对方的效果破坏，对方不能把这张卡作为效果的对象。 ②：只要自己墓地有卡25张以上存在，同调召唤的这张卡的攻击力·守备力上升双方的场上·墓地的卡数量×100。 ③：1回合1次，对方墓地有卡25张以上存在，魔法卡发动时才能发动。那个发动无效并破坏。'),
(21263083, 'Pale Beast', '苍白兽', 'ペイルビースト', 'Normal Monster', 'Beast', 'EARTH', 4, 1500, 1200, '青白色的皮肤，让人感觉恶心的不明怪兽。'),
(61307542, 'Paleozoic Anomalocaris', '伯吉斯异兽·奇虾', 'バージェストマ・アノマロカリス', 'XYZ Monster', 'Aqua', 'WATER', 2, 2400, NULL, '2星怪兽×3只以上 ①：这张卡不受其他怪兽的效果影响。 ②：1回合1次，陷阱卡从自己的魔法与陷阱区域送去墓地的场合才能发动。自己卡组最上面的卡翻开。那张卡是陷阱卡的场合，加入手卡。不是的场合，送去墓地。 ③：这张卡有陷阱卡在作为超量素材的场合，1回合1次，把这张卡1个超量素材取除，以场上1张卡为对象才能发动。那张卡破坏。这个效果在对方回合也能发动。'),
(36346532, 'Paleozoic Cambroraster', '伯吉斯异兽·寒武耙虾', 'バージェストマ・カンブロラスター', 'Link Monster', 'Aqua', 'WATER', NULL, 1200, NULL, '「伯吉斯异兽」怪兽2只 这个卡名的②③的效果1回合各能使用1次。 ①：场上的这张卡不受其他怪兽的效果影响。 ②：以魔法与陷阱区域盖放的1张卡为对象才能发动。那张卡送去墓地，从卡组选1张「伯吉斯异兽」陷阱卡在自己场上盖放。这个效果盖放的卡在盖放的回合也能发动。 ③：自己场上盖放的卡被效果破坏的场合，可以作为代替把场上·墓地的这张卡除外。'),
(98414735, 'Paleozoic Canadia', '伯吉斯异兽·加拿大虫', 'バージェストマ・カナディア', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽变成里侧守备表示。 ②：这张卡在墓地存在，陷阱卡发动时才能发动（同一连锁上最多1次）。这张卡变成通常怪兽（水族·水·2星·攻1200/守0）在怪兽区域特殊召唤（不当作陷阱卡使用）。这个效果特殊召唤的这张卡不受怪兽的效果影响，从场上离开的场合除外。'),
(38761908, 'Paleozoic Dinomischus', '伯吉斯吸虫・足杯虫', 'バージェストマ・ディノミスクス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上1张表侧表示卡为对象才能发动。选自己1张手卡丢弃，作为对象的卡除外。 ②：这张卡在墓地存在，陷阱卡发动时才能发动（同一连锁上最多1次）。这张卡变成通常怪兽（水族·水·2星·攻1200/守0）在怪兽区域特殊召唤（不当作陷阱卡使用）。这个效果特殊召唤的这张卡不受怪兽的效果影响，从场上离开的场合除外。'),
(2376209, 'Paleozoic Eldonia', '伯吉斯异兽·伊尔东钵', 'バージェストマ・エルドニア', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力·守备力直到回合结束时上升500。 ②：陷阱卡发动时，连锁那个发动才能把这个效果在墓地发动。这张卡变成通常怪兽（水族·水·2星·攻1200/守0）在怪兽区域特殊召唤（不当作陷阱卡使用）。这个效果特殊召唤的这张卡不受怪兽的效果影响，从场上离开的场合除外。'),
(61420130, 'Paleozoic Hallucigenia', '伯吉斯异兽·怪诞虫', 'バージェストマ・ハルキゲニア', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力·守备力直到回合结束时变成一半。 ②：陷阱卡发动时，连锁那个发动才能把这个效果在墓地发动。这张卡变成通常怪兽（水族·水·2星·攻1200/守0）在怪兽区域特殊召唤（不当作陷阱卡使用）。这个效果特殊召唤的这张卡不受怪兽的效果影响，从场上离开的场合除外。'),
(1154611, 'Paleozoic Leanchoilia', '伯吉斯异兽·林乔利虫', 'バージェストマ・レアンコイリア', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以除外的1张自己或者对方的卡为对象才能发动。那张卡回到墓地。 ②：陷阱卡发动时，连锁那个发动才能把这个效果在墓地发动。这张卡变成通常怪兽（水族·水·2星·攻1200/守0）在怪兽区域特殊召唤（不当作陷阱卡使用）。这个效果特殊召唤的这张卡不受怪兽的效果影响，从场上离开的场合除外。'),
(64765016, 'Paleozoic Marrella', '伯吉斯异兽·马尔三叶形虫', 'バージェストマ・マーレラ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组把1张陷阱卡送去墓地。 ②：陷阱卡发动时，连锁那个发动才能把这个效果在墓地发动。这张卡变成通常怪兽（水族·水·2星·攻1200/守0）在怪兽区域特殊召唤（不当作陷阱卡使用）。这个效果特殊召唤的这张卡不受怪兽的效果影响，从场上离开的场合除外。'),
(35035481, 'Paleozoic Olenoides', '伯吉斯异兽·拟油栉虫', 'バージェストマ・オレノイデス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。 ②：这张卡在墓地存在，陷阱卡发动时才能发动（同一连锁上最多1次）。这张卡变成通常怪兽（水族·水·2星·攻1200/守0）在怪兽区域特殊召唤（不当作陷阱卡使用）。这个效果特殊召唤的这张卡不受怪兽的效果影响，从场上离开的场合除外。'),
(37649320, 'Paleozoic Opabinia', '伯吉斯异兽·欧巴宾海蝎', 'バージェストマ・オパビニア', 'XYZ Monster', 'Aqua', 'WATER', 2, NULL, 2400, '2星怪兽×2 「伯吉斯异兽·欧巴宾海蝎」的③的效果1回合只能使用1次。 ①：这张卡不受其他怪兽的效果影响。 ②：只要这张卡在怪兽区域存在，自己可以把「伯吉斯异兽」陷阱卡从手卡发动。 ③：这张卡有陷阱卡在作为超量素材的场合，把这张卡1个超量素材取除才能发动。从卡组把1张「伯吉斯异兽」陷阱卡加入手卡。'),
(24903843, 'Paleozoic Pikaia', '伯吉斯异兽·皮卡虫', 'バージェストマ・ピカイア', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从手卡丢弃1张「伯吉斯异兽」卡。那之后，自己从卡组抽2张。 ②：陷阱卡发动时，连锁那个发动才能把这个效果在墓地发动。这张卡变成通常怪兽（水族·水·2星·攻1200/守0）在怪兽区域特殊召唤（不当作陷阱卡使用）。这个效果特殊召唤的这张卡不受怪兽的效果影响，从场上离开的场合除外。'),
(71703785, 'Palladium Oracle Mahad', '守护神官 马哈德', '守護神官マハード', 'Effect Monster', 'Spellcaster', 'LIGHT', 7, 2500, 2100, '①：把这张卡抽到时，把这张卡给对方观看才能发动。这张卡从手卡特殊召唤。 ②：这张卡和暗属性怪兽进行战斗的伤害步骤内，这张卡的攻击力变成2倍。 ③：这张卡被战斗·效果破坏的场合才能发动。从自己的手卡·卡组·墓地把1只「黑魔术师」特殊召唤。'),
(42006475, 'Palladium Oracle Mana', '守护神官 玛娜', '守護神官マナ', 'Effect Monster', 'Spellcaster', 'LIGHT', 6, 2000, 1700, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在，只以自己场上的魔法师族怪兽1只为对象的对方的魔法·陷阱·怪兽的效果发动时才能发动。这张卡特殊召唤。 ②：只要这张卡在怪兽区域存在，自己场上的7星以上的魔法师族怪兽不会被效果破坏。 ③：这张卡被战斗·效果破坏的场合才能发动。从自己的手卡·卡组·墓地选1只「黑魔术少女」特殊召唤。'),
(61116514, 'Palm Ryzeal', '脉离・雷热涡炉', 'パルマ・ライゼオル', 'Effect Monster', 'Thunder', 'FIRE', 4, 1200, 2400, '这张卡不能通常召唤。从自己的手卡·墓地让1只「雷火沸动」怪兽回到卡组·额外卡组的场合可以特殊召唤。 ①：只要这张卡在怪兽区域存在，自己不是4阶超量怪兽不能从额外卡组特殊召唤。 ②：1回合1次，这张卡和对方怪兽进行战斗的伤害计算时才能发动。从手卡·卡组把1只4星怪兽送去墓地，这张卡的攻击力直到战斗阶段结束时上升那个攻击力数值。'),
(39091951, 'Pandaborg', '电子熊猫', 'パンダボーグ', 'Effect Monster', 'Psychic', 'WATER', 4, 1700, 1400, '这张卡被战斗破坏送去墓地时，可以支付800基本分从自己卡组把1只4星的念动力族怪兽特殊召唤。'),
(68299524, 'Pandemic Dragon', '瘟疫龙', 'パンデミック・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 7, 2500, 1000, '①：1回合1次，支付100的倍数的基本分才能发动。这张卡以外的场上的表侧表示怪兽的攻击力下降因为这个效果发动而支付的基本分数值。 ②：1回合1次，以持有这张卡的攻击力以下的攻击力的场上1只怪兽为对象才能发动。那只怪兽破坏。 ③：这张卡被战斗·效果破坏的场合发动。场上的全部表侧表示怪兽的攻击力下降1000。'),
(94585852, 'Pandemonium', '万魔殿-恶魔的巢窟-', '万魔殿－悪魔の巣窟－', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '名称中含有「恶魔」字样的怪兽在准备阶段可以不必支付基本分。当名称中含有「恶魔」字样的怪兽由于战斗以外的方式被破坏送去墓地时，可以从卡组中选择1张等级比被破坏的怪兽等级低，且名称中含有「恶魔」字样的怪兽卡加入手卡。'),
(75375465, 'Pandemonium Watchbear', '地狱的番熊', '地獄の番熊', 'Effect Monster', 'Beast', 'DARK', 4, 1300, 1800, '只要这张卡在自己场上表侧表示存在，自己场上的「万魔殿-恶魔的巢窟-」不会被对方所控制的卡的效果所破坏。'),
(15936370, 'Pandora''s Jewelry Box', '潘德拉宝具箱', 'パンドラの宝具箱', 'Pendulum Effect Monster', 'Wyrm', 'DARK', 4, 1500, 1500, '①：只要自己的额外卡组没有卡存在并有这张卡在怪兽区域存在，自己抽卡阶段的通常抽卡变成2张。'),
(22842126, 'Pantheism of the Monarchs', '泛神的帝王', '汎神の帝王', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：从手卡把1张「帝王」魔法·陷阱卡送去墓地才能发动。自己抽2张。 ②：把墓地的这张卡除外才能发动。从卡组把3张「帝王」魔法·陷阱卡给对方观看，对方从那之中选1张。那1张卡加入自己手卡，剩余回到卡组。'),
(70101178, 'Panther Shark', '豹鲨', 'パンサー・シャーク', 'Effect Monster', 'Fish', 'WATER', 5, 1100, 2000, '对方场上的怪兽是2只以上的场合，这张卡可以不用解放作召唤。此外，自己场上有「鹰鲨」存在的场合，这张卡可以从手卡特殊召唤。「豹鲨」在自己场上只能有1只表侧表示存在。'),
(42035044, 'Panther Warrior', '漆黑之豹战士', '漆黒の豹戦士パンサーウォリアー', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 2000, 1600, '①：只要这张卡在怪兽区域存在，这张卡的攻击宣言之际，自己必须把这张卡以外的自己场上1只怪兽解放。'),
(72959823, 'Panzer Dragon', '重装机甲 战车龙', '重装機甲 パンツァードラゴン', 'Fusion Monster', 'Machine', 'LIGHT', 5, 1000, 2600, '机械族怪兽＋龙族怪兽 ①：这张卡被破坏送去墓地的场合，以场上1张卡为对象才能发动。那张卡破坏。'),
(73776643, 'Papa-Corn', '亲子玉米', 'オヤコーン', 'Effect Monster', 'Plant', 'EARTH', 4, 1200, 800, '场地魔法卡表侧表示存在的场合，这张卡的攻击力上升1000。'),
(57355219, 'Paradox Fusion', '悖论结合', 'パラドックス・フュージョン', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：可以把自己场上1只表侧表示的融合怪兽除外把以下效果发动。发动后第2次的自己结束阶段，除外的那只怪兽表侧攻击表示回到自己场上。 ●魔法·陷阱卡发动时才能发动。那个发动无效并破坏。 ●自己或者对方把怪兽特殊召唤之际才能发动。那次特殊召唤无效，那些怪兽破坏。'),
(71278040, 'Parallel eXceed', '平行超越者', 'パラレルエクシード', 'Effect Monster', 'Cyberse', 'WIND', 8, 2000, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在，自己把怪兽连接召唤的场合才能发动。这张卡在作为那只连接怪兽所连接区的自己场上特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把1只「并行超限龙」特殊召唤。 ③：「并行超限龙」的效果特殊召唤的这张卡的等级变成4星，原本的攻击力·守备力变成一半。'),
(93394164, 'Parallel Panzer', '并行装甲车炮', 'パラレル・パンツァー', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '连接怪兽才能装备。这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，自己主要阶段才能发动。装备怪兽的位置向那只怪兽所连接区的主要怪兽区域移动（不能向从那只怪兽来看的对方场上移动）。 ②：把装备的这张卡送去墓地才能发动。选和这张卡装备过的场上的怪兽相同纵列1张卡破坏。'),
(879958, 'Parallel Port Armor', '并口护甲', 'パラレルポート・アーマー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只连接怪兽为对象才能把这张卡发动。这张卡当作装备卡使用给那只怪兽装备。装备怪兽不会成为对方的效果的对象，不会被战斗破坏。 ②：从自己墓地把这张卡和2只连接怪兽除外，以自己场上1只连接怪兽为对象才能发动。这个回合，那只怪兽在同1次的战斗阶段中可以作2次攻击。'),
(23327298, 'Parallel Selection', '平行选择', 'パラレル・セレクト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的同调怪兽被对方破坏送去墓地时，选择从游戏中除外的1张自己的魔法卡发动。选择的魔法卡加入手卡。'),
(483, 'Parallel Teleport', '平行瞬移', 'パラレル・テレポート', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不是念动力族怪兽不能特殊召唤。 ①：把自己场上1只持有等级的念动力族怪兽解放才能发动。从卡组·额外卡组把1只7星以下的念动力族怪兽特殊召唤。解放的怪兽和这个效果特殊召唤的怪兽的原本等级不同的场合，再让自己失去那个相差×1000基本分。'),
(83102080, 'Parallel Twister', '平行龙卷', 'パラレル・ツイスター', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：把这张卡以外的自己场上1张魔法·陷阱卡送去墓地，以场上1张卡为对象才能发动。那张卡破坏。'),
(54283059, 'Parallel World Fusion', '平行世界融合', '平行世界融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不能用这张卡的效果以外把怪兽特殊召唤。 ①：除外的由「元素英雄」融合怪兽卡决定的自己的融合素材怪兽回到卡组，把那1只融合怪兽从额外卡组融合召唤。'),
(79707116, 'Paralyzing Chain', '麻痹链', 'パラライズ・チェーン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '每次卡的效果从对方卡组把卡送去墓地，给与对方基本分300伤害。'),
(22712877, 'Paralyzing Mushroom', '麻痹盖菇', 'シビレルダケ', 'Effect Monster', 'Thunder', 'LIGHT', 5, 1400, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：原本种族是雷族的怪兽从自己的手卡·场上送去墓地的场合才能发动（伤害步骤也能发动）。这张卡从手卡特殊召唤。 ②：这张卡在怪兽区域存在的状态，雷族怪兽的效果在手卡发动的场合才能发动。在自己场上把1只「电麻衍生物」（雷族·暗·1星·攻/守0）特殊召唤。'),
(50152549, 'Paralyzing Potion', '麻药', 'しびれ薬', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '机械族以外的怪兽装备可能。装备怪兽不能攻击宣言。'),
(37491810, 'Parametalfoes Azortless', '混炼装勇士·阿佐特要塞姬', 'パラメタルフォーゼ・アゾートレス', 'Pendulum Effect Fusion Monster', 'Psychic', 'FIRE', 7, 2500, 2000, '「炼装」怪兽＋融合怪兽 这个卡名的①的怪兽效果1回合只能使用1次。 ①：这张卡从额外卡组的特殊召唤成功的场合，以对方场上1张卡为对象才能发动。从自己的额外卡组让2只表侧表示的灵摆怪兽回到卡组，作为对象的卡破坏。 ②：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(58549532, 'Parametalfoes Fusion', '混炼装融合', '混錬装融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·场上的怪兽以及自己的额外卡组的表侧表示的灵摆怪兽之中把「炼装」融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。那个时候，从手卡·场上·额外卡组各只能有最多1只作为融合素材。'),
(10024317, 'Parametalfoes Melcaster', '混炼装勇士·汞巫', 'パラメタルフォーゼ・メルキャスター', 'Pendulum Effect Monster', 'Psychic', 'FIRE', 7, 2000, 2500, '这个卡名的怪兽效果1回合只能使用1次。 ①：场上的这张卡被战斗·效果破坏的场合才能发动。从自己的额外卡组把「混炼装勇士·汞巫」以外的1只表侧表示的「炼装」灵摆怪兽加入手卡。这个回合，自己不能把这个效果加入手卡的卡以及那些同名卡在灵摆区域发动。'),
(27911549, 'Parasite Paracide', '寄生虫 帕拉赛德', '寄生虫パラサイド', 'Flip Effect Monster', 'Insect', 'EARTH', 2, 500, 300, '反转：把这张卡表面向上混进对方卡组洗切。对方抽到这张卡时，这张卡在对方场上表侧守备表示特殊召唤，给与对方基本分1000分伤害。之后，只要这张卡表侧表示在场上存在，对方场上表侧表示存在的怪兽全部变成昆虫族。'),
(14457896, 'Parasite Paranoid', '寄生虫 帕拉诺伊德', '寄生虫パラノイド', 'Effect Monster', 'Insect', 'EARTH', 2, 500, 300, '这个卡名的①的效果1回合只能使用1次。 ①：以场上1只表侧表示怪兽为对象才能发动。这张卡从手卡当作装备卡使用给那只怪兽装备。装备怪兽种族变成昆虫族，不能向昆虫族怪兽攻击，昆虫族怪兽为对象发动的装备怪兽的效果无效化。这个效果在对方回合也能发动。 ②：当作装备卡使用的这张卡被送去墓地的场合才能发动。从手卡把1只7星以上的昆虫族怪兽无视召唤条件特殊召唤。'),
(87978805, 'Parasitic Ticky', '寄生体 壁虱', '寄生体ダニー', 'Effect Monster', 'Insect', 'EARTH', 1, -1, -1, '这张卡的攻击力·守备力是场上的衍生物的数量×500的数值。'),
(44092304, 'Parasomnia Pillow', '梦迷枕 异睡貘', '夢迷枕パラソムニア', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的结束阶段才能发动。装备怪兽破坏。 ②：装备怪兽被破坏送去墓地让这张卡被送去墓地的场合才能发动。把持有这张卡装备过的怪兽的原本的种族·属性·攻击力的1只「异睡衍生物」（1星·攻?/守0）在自己场上特殊召唤。那之后，这张卡给那衍生物装备。'),
(3289027, 'Parl, Hermit of Dark World', '暗黑界的隐者 珀尔', '暗黒界の隠者 パアル', 'Effect Monster', 'Fiend', 'DARK', 1, 300, 100, '这个卡名的效果1回合只能使用1次。 ①：这张卡被效果从手卡丢弃去墓地的场合，以「暗黑界的隐者 珀尔」以外的自己墓地1只「暗黑界」怪兽为对象才能发动。那只怪兽在自己或者对方场上特殊召唤。被对方的效果丢弃的场合，可以再从自己的手卡·墓地的怪兽以及除外的自己怪兽之中选1只恶魔族怪兽在自己或者对方场上特殊召唤。'),
(88453933, 'Parlor Dragonmaid', '龙女仆・侍应龙女', 'ドラゴンメイド・パルラ', 'Effect Monster', 'Dragon', 'WIND', 3, 500, 1700, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「半龙女仆·客厅龙女」以外的1张「半龙女仆」卡送去墓地。 ②：自己·对方的战斗阶段开始时才能发动。这张卡回到手卡，从自己的手卡·墓地把1只8星「半龙女仆」怪兽特殊召唤。'),
(62762898, 'Parrot Dragon', '鹦鹉龙', 'パロット・ドラゴン', 'Normal Monster', 'Dragon', 'WIND', 5, 2000, 1300, '美国喜剧中的龙，不要被可爱的外表所迷惑。'),
(52228131, 'Parry', '格挡', 'パリィ', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '从手卡把1张名字带有「剑斗兽」的卡回到卡组。陷阱卡的发动无效并破坏。'),
(17988746, 'Parry Knights', '派对夜骑士组', 'パーリィナイツ', 'Effect Monster', 'Warrior', 'EARTH', 6, 2300, 2100, '①：对方怪兽的攻击让自己受到战斗伤害时才能发动。这张卡从手卡特殊召唤。那之后，可以把持有受到的伤害数值以下的攻击力的1只怪兽从手卡特殊召唤。'),
(32872833, 'Parsec, the Interstellar Dragon', '星间龙 秒差龙', '星間竜パーセク', 'Effect Monster', 'Dragon', 'LIGHT', 8, 800, 800, '自己场上有8星的怪兽存在的场合，这张卡可以不用解放作召唤。'),
(29185231, 'Parthian Shot', '一击脱离', '一撃離脱', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：自己·对方的战斗阶段结束时才能发动。变成这个回合的结束阶段。'),
(39261576, 'Particle Fusion', '颗粒融合', 'パーティカル・フュージョン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从自己场上把融合怪兽卡决定的融合素材怪兽送去墓地，把名字带有「宝石骑士」的那1只融合怪兽当作融合召唤从额外卡组特殊召唤。这个效果融合召唤成功时，把墓地存在的这张卡从游戏中除外，选择那次融合召唤使用的1只名字带有「宝石骑士」的融合素材怪兽发动。那只融合怪兽的攻击力直到结束阶段时上升选择的怪兽的攻击力数值。'),
(50292967, 'Past Image', '过去的影像', 'パスト・イメージ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有念动力族怪兽表侧表示存在的场合，选择对方场上存在的1只怪兽才能发动。选择的怪兽从游戏中除外。这个效果除外的怪兽在下次的准备阶段时以相同表示形式回到对方场上。'),
(81481818, 'Patchwork Fluffal', '拼缝型毛绒动物', 'パッチワーク・ファーニマル', 'Effect Monster', 'Fairy', 'EARTH', 1, NULL, NULL, '①：这张卡只要在怪兽区域存在，也当作「魔玩具」怪兽使用。 ②：这张卡只要在怪兽区域存在，可以作为「魔玩具」融合怪兽卡有卡名记述的1只融合素材怪兽的代替。那个时候，其他的融合素材怪兽必须是正规品。'),
(26435595, 'Patissciel Couverture', '圣果使 巧皮儿', '聖菓使クーベル', 'Pendulum Effect Fusion Monster', 'Fairy', 'DARK', 5, 1700, 700, '灵摆怪兽×2 ①：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(19153634, 'Patrician of Darkness', '黑暗贵族', 'ノーブル・ド・ノワール', 'Effect Monster', 'Zombie', 'DARK', 5, 2000, 1400, '只要这张卡在场上表侧表示存在，对方怪兽的攻击对象由这张卡的控制者选择。'),
(71930383, 'Patroid', '警车机人', 'パトロイド', 'Effect Monster', 'Machine', 'EARTH', 4, 1200, 1200, '把对方场上盖放的1张卡翻开，确认后回到原状。这个效果1回合只有1次在自己的主要阶段才能发动。'),
(76775123, 'Patrol Robo', '巡逻机器人', 'パトロール・ロボ', 'Effect Monster', 'Machine', 'EARTH', 3, 1100, 900, '只要这张卡在场上表侧表示存在，自己的准备阶段可以把对方场上盖放的1张卡确认。'),
(77384395, 'Pazuzule', '拼图帕祖祖', 'パズズル', 'Pendulum Effect Monster', 'Fiend', 'DARK', 1, 500, 500, '①：只要这张卡在怪兽区域存在，自己怪兽的灵摆召唤不会被无效化。'),
(14055212, 'Peaceful Burial', '清闲的埋葬', 'のどかな埋葬', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1只怪兽送去墓地。这个回合，自己不能作这个效果送去墓地的卡以及那些同名卡的效果的发动。'),
(82460246, 'Peaceful Planet Calarium', '伍世坏・佳乐里姆', '伍世壊＝カラリウム', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的③的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「末那愚子族」怪兽或者「维萨斯-斯塔弗罗斯特」加入手卡。 ②：自己场上的光属性怪兽的攻击力上升自己的场上·墓地的调整数量×100。 ③：自己场上的表侧表示的调整被战斗·效果破坏的场合，以那1只怪兽为对象才能发动。那只怪兽特殊召唤。'),
(20624263, 'Peacock', '孔雀', 'クジャック', 'Normal Monster', 'Winged Beast', 'WIND', 5, 1700, 1500, '展开美丽的羽毛，从而变成巨大的孔雀开状。扬起羽毛作为攻击手段。'),
(300202001, 'Peak Performance', NULL, NULL, 'Skill Card', 'Kaiba', NULL, NULL, NULL, NULL, NULL),
(52263685, 'Peeking Goblin', '哥布林偷窥者', '盗み見ゴブリン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '对方从卡组上面把3张卡翻开。自己从那之中选择1张回到对方卡组最下面，剩下的卡用喜欢的顺序回到对方卡组上面。'),
(72083436, 'Pegasus Wing', '天马之翼', '天馬の翼', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己墓地有同盟怪兽存在的场合，以自己场上的「女武神」怪兽任意数量为对象才能发动。这个回合，那些怪兽可以直接攻击。那次直接攻击给与对方的战斗伤害变成一半。'),
(967928, 'Penalty Game!', '惩罚游戏！', '罰ゲーム！', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方的手卡4张的时候，选择下面1个效果发动。 ●对方下个抽卡阶段不能抽卡。 ●这个回合对方不能发动魔法·陷阱卡。'),
(58720904, 'Pendransaction', '挂起事务鲸', 'ペンドラザクション', 'XYZ Monster', 'Cyberse', 'WATER', 4, 2000, 1000, '4星怪兽×2 这个卡名的效果1回合只能使用1次。 ①：把这张卡1个超量素材取除才能发动。自己的额外卡组的数量比对方多的场合，那个相差数量的以下效果各适用。 ●1张以上：这张卡的攻击力直到对方回合结束时上升1000。 ●5张以上：这张卡直到对方回合结束时不会成为效果的对象。 ●10张以上：选对方场上1张卡除外。 ●15张以上：对方基本分变成3000。'),
(2359348, 'Pendulum Area', '灵摆区', 'ペンデュラム・エリア', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的怪兽只有灵摆怪兽的场合，以自己的灵摆区域2张卡为对象才能发动。那2张卡破坏，这个回合双方不能作灵摆召唤以外的特殊召唤。'),
(76660409, 'Pendulum Back', '灵摆回归', 'ペンデュラム・バック', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的灵摆区域有2张卡存在的场合，以持有用那些灵摆刻度可以灵摆召唤的等级的自己墓地2只怪兽为对象才能发动。那些怪兽加入手卡。'),
(53208660, 'Pendulum Call', '灵摆呼叫', 'ペンデュラム・コール', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「灵摆呼唤」在1回合只能发动1张，把「魔术师」灵摆怪兽的灵摆效果发动过的回合不能发动。 ①：丢弃1张手卡才能发动。把2只卡名不同的「魔术师」灵摆怪兽从卡组加入手卡。这张卡的发动后，直到下次的对方回合结束时自己的灵摆区域的「魔术师」卡不会被效果破坏。'),
(84274024, 'Pendulum Dimension', '灵摆次元', 'ペンデュラム・ディメンション', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡已在魔法与陷阱区域存在的状态，自己用灵摆怪兽为素材对以下怪兽的特殊召唤成功的场合才能发动。这个回合，自己的「灵摆次元」的效果不能有相同效果适用。 ●融合：从卡组把原本等级和那只融合怪兽相同的1只怪兽效果无效守备表示特殊召唤。 ●同调：从卡组把1张「融合」加入手卡。 ●超量：从卡组把持有那只超量怪兽的阶级数值以下的等级的1只调整加入手卡或特殊召唤。'),
(6992184, 'Pendulum Encore', '灵摆返场', 'ペンデュラム・アンコール', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方主要阶段，丢弃1张手卡才能发动。把灵摆怪兽灵摆召唤。这个回合，自己的灵摆区域的卡不能把效果发动，不会被自己的卡的效果破坏，结束阶段回到持有者卡组。'),
(55795155, 'Pendulum Evolution', '灵摆进化', 'ペンデュラム・エボリューション', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：从手卡让1只灵摆怪兽回到卡组才能发动。和回去的怪兽卡名不同的1只攻击力2500的灵摆怪兽从卡组加入手卡。 ②：自己把额外卡组的里侧的灵摆怪兽特殊召唤的回合的自己主要阶段才能发动。进行怪兽的灵摆召唤。 ③：以自己场上1只「霸王龙 扎克」为对象才能发动。这个回合，那只怪兽可以向对方怪兽全部各作1次攻击。'),
(65646587, 'Pendulum Fusion', '灵摆结合', 'ペンデュラム・フュージョン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己场上把融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。自己的灵摆区域有2张卡存在的场合，自己的灵摆区域存在的融合素材怪兽也能作为融合素材使用。'),
(36111775, 'Pendulum Halt', '灵摆停顿', 'ペンデュラム・ホルト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的额外卡组有表侧表示的灵摆怪兽3种类以上存在的场合才能发动。自己从卡组抽2张。这张卡的发动后，直到回合结束时自己不能从卡组把卡加入手卡。'),
(68477598, 'Pendulum Hole', '灵摆洞', 'ペンデュラム・ホール', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：自己或者对方把怪兽灵摆召唤之际才能发动。那次灵摆召唤无效，那些怪兽回到持有者卡组。'),
(60434189, 'Pendulum Impenetrable', '灵摆延缓', 'ペンデュラム・モラトリアム', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：这个回合，自己以及对方的灵摆区域的卡不会被对方的效果破坏，以灵摆区域的卡为对象的对方发动的效果无效化。'),
(24433920, 'Pendulum Machine', '单摆刃拷问机械', '振り子刃の拷問機械', 'Normal Monster', 'Machine', 'DARK', 6, 1750, 2000, '大型单摆刀刃把对方劈成两半！很恐怖的拷问机械。'),
(38203732, 'Pendulum Paradox', '灵摆悖论', 'ペンデュラム・パラドックス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的额外卡组的表侧表示的灵摆怪兽之中选2只灵摆刻度相同而卡名不同的怪兽加入手卡。'),
(65914127, 'Pendulum Pendant', '灵摆吊坠', 'ペンデュラム・ペンダント', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从额外卡组（表侧）把5只灵摆怪兽除外才能发动。从自己的卡组·额外卡组（表侧）把1只灵摆怪兽在自己的灵摆区域放置。 ②：把墓地的这张卡除外，以自己或对方的灵摆区域1张卡为对象才能发动。那张卡的灵摆刻度下降1（最少到0）。'),
(77826734, 'Pendulum Reborn', '灵摆重生', 'ペンデュラム・リボーン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：选1只自己的额外卡组的表侧表示的灵摆怪兽或者自己墓地的灵摆怪兽特殊召唤。'),
(74926274, 'Pendulum Rising', '灵摆显现', 'ペンデュラム・アライズ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「灵摆显现」在1回合只能发动1张。 ①：把自己场上1只怪兽送去墓地才能发动。和那只怪兽的原本等级相同等级的1只灵摆怪兽从卡组特殊召唤。这个效果特殊召唤的怪兽在结束阶段破坏。'),
(17885118, 'Pendulum Scale', '灵摆刻度', 'ペンデュラム・スケール', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己的灵摆区域有2张卡存在的场合，那个灵摆刻度差的数值的以下效果适用。 ●0：选场上2张魔法·陷阱卡破坏。 ●1～3：从卡组把1只2～4星的灵摆怪兽加入手卡。 ●4～6：从卡组把1只5～7星的灵摆怪兽加入手卡。 ●7以上：选自己的灵摆区域最多2张卡回到持有者手卡。那之后，可以从手卡把1只灵摆怪兽特殊召唤。'),
(69982329, 'Pendulum Shift', '灵摆转动', 'ペンデュラム・ターン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以自己或者对方的灵摆区域1张卡为对象，宣言1～10的灵摆刻度才能发动。这个回合，那张卡变成宣言的灵摆刻度。'),
(83461421, 'Pendulum Storm', '灵摆风暴', 'ペンデュラム・ストーム', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：双方的灵摆区域的卡全部破坏。那之后，可以选对方场上1张魔法·陷阱卡破坏。'),
(42378577, 'Pendulum Switch', '灵摆切换', 'ペンデュラム・スイッチ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己的灵摆区域1张卡为对象才能发动。那张卡特殊召唤。 ②：以自己的怪兽区域1只灵摆怪兽为对象才能发动。那只灵摆怪兽在自己的灵摆区域放置。'),
(19501924, 'Pendulum Transfer', '灵摆转移', 'ペンデュラム・シフト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上最多2只灵摆怪兽为对象才能发动。那些自己的灵摆怪兽在自己的灵摆区域放置。'),
(26237713, 'Pendulum Treasure', '灵摆宝藏', 'ペンデュラム・トレジャー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1只灵摆怪兽表侧加入额外卡组。'),
(43502497, 'Pendulum Witch', '灵摆魔女', 'ペンデュラム・ウィッチ', 'Pendulum Effect Monster', 'Spellcaster', 'EARTH', 3, 1500, 800, '这个卡名的①的怪兽效果1回合只能使用1次。 ①：这张卡召唤·灵摆召唤的场合，以自己的灵摆区域1张卡为对象才能发动。那张卡和这张卡破坏，从卡组把1只4星以下的灵摆怪兽加入手卡。 ②：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(46005939, 'Pendulum Xyz', '灵摆超量', 'ペンデュラム・エクシーズ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己的灵摆区域2张卡为对象才能发动。那2张卡效果无效特殊召唤，只用那2只怪兽为素材把1只超量怪兽超量召唤。那个时候，要作为超量素材的1只怪兽的等级可以当作和另1只怪兽相同等级使用。'),
(66150724, 'PenduLuMoon', '灵摆明月', 'ペンデュラムーン', 'Pendulum Effect Monster', 'Spellcaster', 'LIGHT', 1, 200, 700, '这个卡名的怪兽效果1回合只能使用1次。 ①：自己主要阶段才能发动。从自己的额外卡组把持有用自己的灵摆区域2张卡的灵摆刻度可以灵摆召唤的等级的最多2只表侧表示的灵摆怪兽加入手卡。这个效果的发动后，直到回合结束时自己只要灵摆召唤不成功，不能把怪兽的效果发动，自己的灵摆区域的卡的效果无效化。'),
(18210764, 'Pendulumucho', '灵摆姆啾', 'ペンデュラムーチョ', 'Pendulum Effect Monster', 'Winged Beast', 'EARTH', 1, NULL, NULL, '①：这张卡召唤·特殊召唤成功的场合才能发动。从自己的额外卡组把「灵摆多福鸟」以外的1只表侧表示的1星灵摆怪兽特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合除外。'),
(8778267, 'Penetration Fusion', '贯穿结合', 'ペネトレーション・フュージョン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：怪兽被战斗破坏的回合才能发动。自己的手卡·场上的怪兽作为融合素材，把1只融合怪兽融合召唤。这个效果特殊召唤的怪兽得到以下效果。 ●自己·对方回合，把这张卡解放，以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力上升500。'),
(91397409, 'Penguin Brave', '企鹅勇者', 'ペンギン勇者', 'Synchro Monster', 'Aqua', 'WATER', 6, 2400, 1200, '调整＋调整以外的怪兽1只以上 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡同调召唤成功的场合才能发动。从卡组把1只「企鹅」怪兽里侧守备表示特殊召唤。 ②：只要这张卡在怪兽区域存在，自己场上的里侧守备表示怪兽不会成为对方的效果的对象。 ③：对方把怪兽的效果发动时才能发动。选自己场上1只里侧守备表示的水属性怪兽变成表侧守备表示。'),
(73640163, 'Penguin Cleric', '企鹅僧侣', 'ペンギン僧侶', 'Effect Monster', 'Aqua', 'WATER', 3, 600, 1700, '这个卡名的①的效果1回合只能使用1次。 ①：「企鹅」怪兽被对方从自己的怪兽区域送去自己墓地的场合，以那之内的1只为对象才能发动（伤害步骤也能发动）。这张卡从手卡丢弃，作为对象的怪兽里侧守备表示特殊召唤。 ②：1回合1次，以自己场上1只「企鹅」怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升600，自己回复600基本分。'),
(36039163, 'Penguin Knight', '企鹅骑士', 'ペンギン・ナイト', 'Effect Monster', 'Aqua', 'WATER', 3, 900, 800, '这张卡被对方的效果从卡组送去墓地时，把自己墓地存在的全部卡回到卡组。'),
(41255165, 'Penguin Ninja', '企鹅忍者', 'ペンギン忍者', 'Flip Effect Monster', 'Aqua', 'WATER', 3, 1400, 700, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡反转的场合，以对方场上最多2张魔法·陷阱卡为对象才能发动。那些卡回到持有者手卡。 ②：以自己场上1只「企鹅」怪兽为对象才能发动。那只怪兽变成里侧守备表示。'),
(93920745, 'Penguin Soldier', '企鹅士兵', 'ペンギン・ソルジャー', 'Flip Effect Monster', 'Aqua', 'WATER', 2, 750, 500, '①：这张卡反转的场合，以场上最多2只怪兽为对象才能发动。那些怪兽回到持有者手卡。'),
(14761450, 'Penguin Squire', '企鹅勇士', 'ペンギン勇士', 'Tuner Monster', 'Aqua', 'WATER', 5, 1800, 600, '这个卡名的①②的效果1回合各能使用1次，把这张卡作为同调素材的场合，不是水属性怪兽的同调召唤不能使用。 ①：自己场上有怪兽被盖放的场合才能发动。这张卡从手卡特殊召唤。那之后，可以让这张卡的等级下降1星或者2星。 ②：以自己场上1只里侧守备表示怪兽为对象才能发动。那只怪兽变成表侧守备表示。这个效果把「企鹅」怪兽以外的怪兽变成表侧守备表示的场合，那个效果无效化。'),
(69792699, 'Penguin Sword', '企鹅剑', 'ペンギン・ソード', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「企鹅」怪兽才能装备。这个卡名的③的效果1回合只能使用1次。 ①：装备怪兽的攻击力上升800。 ②：装备怪兽给与对方战斗伤害时才能发动。选对方场上1张卡回到持有者手卡。 ③：对方场上的表侧表示的卡因「企鹅」卡的效果从场上离开，回到手卡的场合或者被除外的场合发动。直到下个回合的结束时，那些卡以及原本卡名和那些卡相同的卡的效果无效化。'),
(17679043, 'Penguin Torpedo', '企鹅鱼雷', 'ペンギン魚雷', 'Effect Monster', 'Aqua', 'WATER', 3, 550, 300, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡可以直接攻击。 ②：这张卡给与对方战斗伤害时，以对方场上1只6星以下的怪兽为对象才能发动。那只怪兽的控制权直到结束阶段得到。这个效果得到控制权的怪兽的效果无效化，不能攻击宣言。 ③：这张卡攻击的伤害步骤结束时发动。这张卡破坏。'),
(73193552, 'Pennant of Revolution', '革命之御旗', '革命の御旗', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡以外的自己场上的卡被战斗·效果破坏的场合才能发动。从自己的卡组·墓地选1张「自由解放」加入手卡。 ②：包含同调怪兽的怪兽之间进行战斗的伤害步骤开始时才能发动。那只进行战斗的对方怪兽破坏。 ③：魔法与陷阱区域的这张卡被效果破坏的场合，可以作为代替把自己场上1只怪兽破坏。'),
(72336818, 'Pentestag', '渗透测试锹形虫', 'ペンテスタッグ', 'Link Monster', 'Cyberse', 'DARK', NULL, 1600, NULL, '效果怪兽2只 ①：只要这张卡在怪兽区域存在，连接状态的自己怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(64751286, 'Penumbral Soldier Lady', '月之女战士', '月の女戦士', 'Effect Monster', 'Warrior', 'DARK', 6, 2100, 1400, '与光属性怪兽战斗的场合，在伤害步骤内这张卡攻击力上升1000。'),
(12143771, 'People Running About', '流离的饥民', '逃げまどう民', 'Normal Monster', 'Pyro', 'FIRE', 2, 600, 600, '一直在忍受着饥饿的痛苦，发誓一定要发起革命的人民。'),
(71564150, 'Perditious Puppeteer', '地狱的傀儡魔人', '地獄の傀儡魔人', 'Effect Monster', 'Fiend', 'DARK', 7, 2700, 500, '1回合1次，可以丢弃1张手卡，对方场上表侧表示存在的全部3星以下的怪兽的控制权直到结束阶段时得到。这个效果得到控制权的怪兽不能把效果发动，也不能解放和作为同调素材。'),
(18891691, 'Perfect Machine King', '完美机械王', 'パーフェクト機械王', 'Effect Monster', 'Machine', 'EARTH', 8, 2700, 1500, '场上存在的这张卡以外的机械族怪兽每有1只，这张卡的攻击力上升500。'),
(13764602, 'Perfect Sync - A-Un', '阿吽呼吸', '阿吽の呼吸', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「双天」怪兽加入手卡。 ②：自己场上有「双天」效果怪兽存在的场合才能发动。在自己场上把1只「双天魂衍生物」（战士族·光·2星·攻/守0）特殊召唤。这个效果的发动后，直到回合结束时自己不是融合怪兽不能从额外卡组特殊召唤。'),
(48579379, 'Perfectly Ultimate Great Moth', '究极完全态大飞蛾', '究極完全態・グレート・モス', 'Effect Monster', 'Insect', 'EARTH', 8, 3500, 3000, '这张卡不能通常召唤。把有「进化之茧」装备的状态用自己回合计算经过6回合以上的自己场上1只「飞蛾宝宝」解放的场合可以特殊召唤。'),
(6471156, 'Perform Puppet', '操演傀偶', 'パフォーム・パペット', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己墓地把1只「机关傀儡」怪兽除外才能发动。自己场上的全部怪兽的等级直到回合结束时变成和除外的怪兽相同等级。 ②：自己场上的表侧表示的「机关傀儡」怪兽被战斗或者对方的效果破坏送去墓地的场合，以除外的1只自己的「机关傀儡」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(92530005, 'Performage Ball Balancer', '娱乐巫师・骑球手', 'Emボール・ライダー', 'Pendulum Effect Monster', 'Spellcaster', 'EARTH', 4, 1000, 1800, '这个卡名的①②③的怪兽效果1回合各能使用1次。 ①：自己场上有「娱乐法师」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合，可以从以下效果选择1个发动。 ●从卡组把1只「娱乐法师」灵摆怪兽表侧加入额外卡组。 ●自己场上1张「娱乐法师」怪兽卡破坏。 ③：特殊召唤的对方怪兽的直接攻击宣言时才能发动。这张卡从墓地特殊召唤。'),
(6812770, 'Performage Cup Tricker', '娱乐巫师・杯子戏法师', 'Emカップ・トリッカー', 'Pendulum Effect Monster', 'Spellcaster', 'LIGHT', 5, 1200, 1400, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，以场上1只超量怪兽为对象才能发动。那只怪兽1个超量素材取除，这张卡特殊召唤。那之后，场上1只超量怪兽的攻击力下降600。 ②：超量素材的这张卡为让超量怪兽的效果发动而被取除送去墓地的场合，以自己场上2只超量怪兽为对象才能发动。那之内的1只的1个超量素材作为另1只的超量素材。'),
(68819554, 'Performage Damage Juggler', '娱乐巫师・伤害杂耍人', 'Emダメージ・ジャグラー', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1500, 1000, '这个卡名的③的效果1回合只能使用1次。 ①：给与自己伤害的魔法·陷阱·怪兽的效果发动时，把这张卡从手卡丢弃才能发动。那个发动无效并破坏。 ②：自己·对方的战斗阶段，把这张卡从手卡丢弃才能发动。这个回合，自己受到的战斗伤害只有1次变成0。 ③：把墓地的这张卡除外才能发动。从卡组把「娱乐法师 伤害杂耍人」以外的1只「娱乐法师」怪兽加入手卡。'),
(7934362, 'Performage Fire Dancer', '娱乐巫师・火舞者', 'Emファイヤー・ダンサー', 'Pendulum Effect Monster', 'Spellcaster', 'FIRE', 4, 1400, 1200, '这个卡名的①的怪兽效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「娱乐法师 火舞者」以外的1只「娱乐法师」怪兽加入手卡。 ②：场上的这张卡被战斗·效果破坏的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力下降500。'),
(4807253, 'Performage Flame Eater', '娱乐巫师・火焰吞噬者', 'Emフレイム・イーター', 'Effect Monster', 'Spellcaster', 'FIRE', 4, 1200, 1600, '①：给与自己伤害的魔法·陷阱·怪兽的效果发动时才能发动。这张卡从手卡特殊召唤，那个效果让自己受到的伤害变成0。这个回合，自己不是「娱乐法师」怪兽不能特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：这张卡召唤·特殊召唤成功的场合发动。双方玩家受到500伤害。'),
(31292357, 'Performage Hat Tricker', '娱乐巫师・帽子戏法师', 'Emハットトリッカー', 'Effect Monster', 'Spellcaster', 'EARTH', 4, 1100, 1100, '①：场上有怪兽2只以上存在的场合，这张卡可以从手卡特殊召唤。 ②：给与自己伤害的魔法·陷阱·怪兽的效果发动时才能发动。给这张卡放置1个娱乐法师指示物（最多3个）。那之后，那个效果让自己受到的伤害变成0。 ③：这张卡有娱乐法师指示物被放置，那些娱乐法师指示物变成3个时，这张卡的攻击力·守备力变成3300。'),
(71578874, 'Performage Mirror Conductor', '娱乐巫师・镜子指挥', 'Emミラー・コンダクター', 'Pendulum Effect Monster', 'Spellcaster', 'LIGHT', 4, 600, 1400, '①：1回合1次，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力·守备力直到回合结束时交换。那之后，自己受到500伤害。这个效果在对方回合也能发动。'),
(7563579, 'Performage Plushfire', '娱乐巫师・火布偶', 'Emヒグルミ', 'Pendulum Effect Monster', 'Spellcaster', 'FIRE', 4, 1000, 1000, '这个卡名的怪兽效果1回合只能使用1次。 ①：场上的这张卡被战斗·效果破坏的场合才能发动。从手卡·卡组把「娱乐法师 火布偶」以外的1只「娱乐法师」怪兽特殊召唤。'),
(69655484, 'Performage Shadow Maker', '娱乐巫师 影绘师创影者', 'Em影絵師シャドー・メイカー', 'XYZ Monster', 'Spellcaster', 'DARK', 5, 2600, 1000, '5星怪兽×3 这个卡名的①③的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除，从卡组把1只「娱乐法师」怪兽送去墓地才能发动。从卡组把1张「升阶魔法」魔法卡加入手卡。 ②：这张卡为对象的效果发动时，把这张卡1个超量素材取除才能发动。从额外卡组把1只「娱乐法师 影绘师」特殊召唤。 ③：这张卡的超量素材全部被取除的场合才能发动。从自己墓地把1只「娱乐法师」怪兽特殊召唤。'),
(4081665, 'Performage Stilts Launcher', '娱乐巫师・竹马射手', 'Emスティルツ・シューター', 'Effect Monster', 'Spellcaster', 'EARTH', 6, 2200, NULL, '「娱乐法师 高跷射手」的②的效果1回合只能使用1次。 ①：场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤过的回合，自己不能通常召唤。 ②：自己墓地有这张卡以外的「娱乐法师」怪兽存在，给与对方伤害的魔法·陷阱·怪兽的效果发动时，把墓地的这张卡除外才能发动。给与对方2000伤害。'),
(6659193, 'Performage Trapeze High Magician', '娱乐巫师 高空秋千超魔术师', 'Emトラピーズ・ハイ・マジシャン', 'XYZ Monster', 'Spellcaster', 'LIGHT', 5, 2700, 2200, '魔法师族5星怪兽×2 ①：持有超量素材的这张卡不会被战斗·效果破坏。 ②：只要这张卡在怪兽区域存在，自己受到的效果伤害由对方代受（这个效果在1回合可以适用最多有这张卡的超量素材数量的次数）。 ③：这张卡有「娱乐法师 秋千魔术家」在作为超量素材的场合，得到以下效果。 ●把这张卡1个超量素材取除才能发动。这个回合，这张卡在同1次的战斗阶段中可以作3次攻击。'),
(17016362, 'Performage Trapeze Magician', '娱乐巫师 高空秋千魔术师', 'Emトラピーズ・マジシャン', 'XYZ Monster', 'Spellcaster', 'LIGHT', 4, 2500, 2000, '魔法师族4星怪兽×2 ①：只要这张卡在怪兽区域存在，自己不会受到这张卡的攻击力以下的战斗·效果伤害。 ②：自己·对方的主要阶段1有1次，把这张卡1个超量素材取除，以回合玩家的场上1只其他的表侧攻击表示怪兽为对象才能发动。这个回合，那只怪兽可以作2次攻击，战斗阶段结束时破坏。 ③：这张卡被战斗或者对方的效果破坏送去墓地的场合才能发动。从卡组把1只「娱乐法师」怪兽特殊召唤。'),
(33206889, 'Performage Trapeze Witch', '娱乐巫师 高空秋千力量魔女', 'Emトラピーズ・フォース・ウィッチ', 'Fusion Monster', 'Spellcaster', 'DARK', 7, 2400, 1800, '「娱乐法师」怪兽×2 ①：只要这张卡在怪兽区域存在，自己场上的「娱乐法师」怪兽不会被自己的卡的效果破坏，对方不能把那些作为效果的对象。 ②：只要自己场上有「娱乐法师 秋千魄力魔女」以外的「娱乐法师」怪兽存在，对方怪兽不能选择这张卡作为攻击对象。 ③：自己的「娱乐法师」怪兽和对方怪兽进行战斗的攻击宣言时才能发动。那只对方怪兽的攻击力下降600。'),
(67696066, 'Performage Trick Clown', '娱乐巫师・戏法小丑', 'Emトリック・クラウン', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1600, 1200, '这个卡名的效果1回合只能使用1次。 ①：这张卡被送去墓地的场合，以自己墓地1只「娱乐法师」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的攻击力·守备力变成0。那之后，自己受到1000伤害。'),
(34323367, 'Performage Water Dancer', '娱乐巫师・水舞者', 'Emウォーター・ダンサー', 'Pendulum Effect Monster', 'Spellcaster', 'WATER', 4, 1200, 1400, '这个卡名的①的怪兽效果1回合只能使用1次。 ①：这张卡灵摆召唤的场合才能发动。从自己的卡组·墓地把1张「融合」加入手卡。 ②：场上的这张卡被战斗·效果破坏的场合，以场上1只攻击表示怪兽为对象才能发动。那只怪兽变成守备表示。'),
(70417076, 'Performage Wind Drainer', '娱乐巫师・吸风者', 'Emウィンド・サッカー', 'Pendulum Effect Monster', 'Spellcaster', 'WIND', 5, 2100, NULL, '这个卡名的①的怪兽效果1回合只能使用1次。 ①：对方场上有怪兽存在的场合或者场上有「娱乐法师」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。只要这个效果特殊召唤的这张卡在怪兽区域存在，自己不是「娱乐法师」怪兽不能特殊召唤。 ②：这张卡特殊召唤的场合才能发动。这张卡的等级下降1星。 ③：1回合1次，可以发动。自己场上的全部4星「娱乐法师」怪兽的等级变成5星。'),
(46066477, 'Performance Hurricane', '娱乐乐队飓风', 'エンタメ・バンド・ハリケーン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「娱乐乐队飓风」在1回合只能发动1张。 ①：以最多有自己场上的「娱乐伙伴」怪兽数量的对方场上的卡为对象才能发动。那些卡回到持有者手卡。'),
(4849037, 'Performance of Sword', '舞蹈战士', 'ダンシング・ソルジャー', 'Ritual Monster', 'Warrior', 'EARTH', 6, 1950, 1850, '「诱发之舞」降临。必须从场地和手卡把等级直到6以上的卡作为祭品。'),
(66768175, 'Performapal Ballad', '娱乐伙伴 歌谣蔷薇', 'EMバラード', 'Pendulum Effect Monster', 'Plant', 'EARTH', 3, 500, 1100, '①：自己的「娱乐伙伴」怪兽攻击的伤害计算后，以对方场上1只表侧表示怪兽为对象才能发动。那只对方怪兽的攻击力下降那只「娱乐伙伴」怪兽的攻击力数值。'),
(19050066, 'Performapal Barokuriboh', '娱乐伙伴 巴洛克栗子球', 'EMバロックリボー', 'Pendulum Effect Monster', 'Fiend', 'DARK', 8, 300, 3000, '①：自己怪兽被战斗破坏时才能发动。这张卡从手卡特殊召唤。 ②：只要这张卡在怪兽区域存在，对方不能选择其他怪兽作为攻击对象。 ③：这张卡被攻击的场合，伤害步骤结束时变成攻击表示。'),
(92767273, 'Performapal Barracuda', '娱乐伙伴 凶猛蔷薇', 'EMバラクーダ', 'Pendulum Effect Monster', 'Plant', 'EARTH', 3, 500, 1100, '「娱乐伙伴 凶猛蔷薇」的怪兽效果1回合只能使用1次。 ①：以持有和原本攻击力不同攻击力的1只「娱乐伙伴」怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升和那个原本攻击力的相差数值。这个效果在对方回合也能发动。'),
(89113320, 'Performapal Bit Bite Turtle', '娱乐伙伴 鱼饵大头龟', 'EMビッグバイトタートル', 'Pendulum Effect Monster', 'Reptile', 'WATER', 3, 800, 1200, '①：这张卡被战斗破坏时才能发动。把让这张卡破坏的怪兽破坏。'),
(72708264, 'Performapal Bot-Eyes Lizard', '娱乐伙伴 机械眼蜥蜴', 'EMボットアイズ・リザード', 'Effect Monster', 'Reptile', 'EARTH', 4, 1600, 1200, '①：这张卡召唤·特殊召唤成功的回合的自己主要阶段只有1次，从卡组把1只「异色眼」怪兽送去墓地才能发动。直到结束阶段，这张卡当作和送去墓地的怪兽同名卡使用。'),
(37745740, 'Performapal Bowhopper', '娱乐伙伴 弩弓蝗虫', 'EMガンバッター', 'Effect Monster', 'Insect', 'EARTH', 4, 1500, 1000, '「娱乐伙伴 弩弓蝗虫」的①②的效果1回合各能使用1次。 ①：把自己场上1只「娱乐伙伴」怪兽解放才能发动。给与对方解放的怪兽的等级×100伤害。 ②：把自己场上1只「娱乐伙伴」怪兽解放，以解放的怪兽以外的自己墓地1只「娱乐伙伴」怪兽为对象才能发动。那只怪兽加入手卡。'),
(34379489, 'Performapal Bubblebowwow', '娱乐伙伴 泡泡斗牛犬', 'EMバブルドッグ', 'Pendulum Effect Monster', 'Beast', 'EARTH', 6, 2300, 1000, '①：这张卡从额外卡组的特殊召唤成功时才能发动。这个回合，从额外卡组特殊召唤的自己场上的灵摆怪兽不会被效果破坏。'),
(22765132, 'Performapal Call', '娱乐伙伴呼唤', 'EMコール', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的直接攻击宣言时，以那1只攻击怪兽为对象才能发动。那次攻击无效，守备力合计最多到作为对象的怪兽的攻击力以下为止，从卡组把最多2只「娱乐伙伴」怪兽加入手卡。这张卡的发动后，直到下次的自己回合的结束时自己不能从额外卡组把怪兽特殊召唤。'),
(44481227, 'Performapal Camelump', '娱乐伙伴 降落驼', 'EMラクダウン', 'Pendulum Effect Monster', 'Beast', 'EARTH', 4, 800, 1800, '①：这张卡被战斗破坏的场合才能发动。让把这张卡破坏的怪兽的攻击力下降800。'),
(37256334, 'Performapal Card Gardna', '娱乐伙伴 纸牌守卫者', 'EMカード・ガードナー', 'Pendulum Effect Monster', 'Rock', 'EARTH', 3, 1000, 1000, '①：这张卡的守备力上升这张卡以外的自己场上的「娱乐伙伴」怪兽的原本守备力的合计数值。'),
(58092907, 'Performapal Celestial Magician', '娱乐伙伴 天空的魔术师', 'EM天空の魔術師', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 4, 1500, 1000, '这个卡名的怪兽效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的回合的自己主要阶段才能发动。这张卡以外的自己场上的怪兽种类在这个回合让以下效果各适用。 ●融合：这张卡可以直接攻击。 ●同调：对方不能把怪兽的效果发动。 ●超量：这张卡的攻击力变成原本攻击力的2倍。 ●灵摆：结束阶段，从卡组把1只灵摆怪兽加入手卡。'),
(69228245, 'Performapal Changeraffe', '娱乐伙伴 变形链长颈鹿', 'EMチェーンジラフ', 'Pendulum Effect Monster', 'Beast', 'EARTH', 1, 100, 500, '①：这张卡召唤·特殊召唤成功时，以对方场上1只表侧表示怪兽为对象才能发动。这只怪兽表侧表示存在期间，作为对象的表侧表示怪兽不能攻击，效果无效化。'),
(17857780, 'Performapal Cheermole', '娱乐伙伴 啦啦队鼹鼠', 'EMチアモール', 'Pendulum Effect Monster', 'Beast', 'EARTH', 2, 600, 1000, '「娱乐伙伴 啦啦队鼹鼠」的怪兽效果1回合只能使用1次。 ①：自己主要阶段以持有和原本攻击力不同攻击力的1只怪兽为对象才能发动。那只怪兽的攻击力数值的以下效果适用。 ●那只怪兽的攻击力比原本攻击力高的场合，那只怪兽的攻击力上升1000。 ●那只怪兽的攻击力比原本攻击力低的场合，那只怪兽的攻击力下降1000。'),
(55554175, 'Performapal Classikuriboh', '娱乐伙伴 古典栗子球', 'EMクラシックリボー', 'Pendulum Effect Monster', 'Fiend', 'DARK', 1, 300, 200, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：把这张卡从手卡丢弃，以自己的灵摆区域1张卡为对象才能发动。那张卡的灵摆刻度直到回合结束时变成1。 ②：这张卡在墓地存在，自己受到战斗伤害时才能发动。这张卡在自己的灵摆区域放置。 ③：这张卡被自身的灵摆效果破坏的场合发动。战斗阶段结束。'),
(8820526, 'Performapal Clay Breaker', '娱乐伙伴 黏土破坏者', 'EMクレイブレイカー', 'Effect Monster', 'Warrior', 'EARTH', 6, 2000, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：上级召唤的这张卡和对方怪兽进行战斗的伤害计算时才能发动。那只对方怪兽的攻击力直到回合结束时下降自己的额外卡组的表侧表示的灵摆怪兽数量×500。 ②：这张卡在墓地存在，自己把2只以上的怪兽同时灵摆召唤时才能发动。墓地的这张卡加入手卡。'),
(9000988, 'Performapal Coin Dragon', '娱乐伙伴 小判龙', 'EM小判竜', 'Pendulum Effect Monster', 'Dragon', 'WATER', 4, 1700, 1000, '①：只要这张卡在怪兽区域存在，这张卡以外的自己场上的龙族怪兽攻击力上升500，不会被效果破坏。'),
(33103459, 'Performapal Corn', '娱乐伙伴 小角', 'EMコン', 'Effect Monster', 'Beast-Warrior', 'LIGHT', 3, 600, 1000, '①：这张卡召唤·特殊召唤成功的回合的自己主要阶段只有1次，以这张卡以外的自己场上1只攻击力1000以下的「娱乐伙伴」怪兽为对象才能发动。自己场上的同是表侧攻击表示的那只怪兽和这张卡变成守备表示，从卡组把1只「异色眼」怪兽加入手卡。 ②：对方回合，从自己墓地把这张卡和1只「娱乐伙伴 小角」以外的「娱乐伙伴」怪兽除外才能发动。自己回复500基本分。');